import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Configuration Reference","description":"Every Blue Server Properties Editor setting — the admin option, editor behavior, and the conf.yml manifest.","frontmatter":{"title":"Configuration Reference","description":"Every Blue Server Properties Editor setting — the admin option, editor behavior, and the conf.yml manifest."},"headers":[],"relativePath":"blue-server-properties/configuration/reference.md","filePath":"blue-server-properties/configuration/reference.md","lastUpdated":1785522590000}'),n={name:"blue-server-properties/configuration/reference.md"};function a(i,e,c,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><h2 id="admin-settings" tabindex="-1">Admin settings <a class="header-anchor" href="#admin-settings" aria-label="Permalink to &quot;Admin settings&quot;">​</a></h2><p>Managed at <strong>Admin → Extensions → Blue Server Properties Editor</strong> (<code>/admin/extensions/blueserverproperties</code>).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>navbar_text</code></td><td>string (max 30, required)</td><td><code>Server Properties</code></td><td>Label of the sidebar tab shown inside servers. Stored in <code>storage/app/blueserverproperties_config.json</code> (not the database) and served to the frontend via <code>GET /api/client/extensions/blueserverproperties/settings/nav-text</code>. Applied live by the <code>NavButtonUpdater</code> components on every server page.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Blueprint paths only</p><p>The admin page, the config JSON, and the live label updates are Blueprint-only. On the Blueprint-free (<code>data/PanelFiles/</code>) path the tab is always named <code>Server Properties</code>.</p></div><h2 id="editor-behavior-built-in" tabindex="-1">Editor behavior (built-in) <a class="header-anchor" href="#editor-behavior-built-in" aria-label="Permalink to &quot;Editor behavior (built-in)&quot;">​</a></h2><p>These are hard-coded editor behaviors, documented so you know what to expect:</p><table tabindex="0"><thead><tr><th>Behavior</th><th>Detail</th></tr></thead><tbody><tr><td>Key normalization</td><td><code>server.properties</code> keys are shown with dashes instead of dots (<code>view-distance</code> ↔ <code>view.distance</code>). The editor maps them back on save.</td></tr><tr><td>Boolean keys</td><td>Any key whose value is <code>true</code>/<code>false</code> renders as a <strong>toggle</strong>.</td></tr><tr><td><code>difficulty</code></td><td>Dropdown: <code>peaceful</code>, <code>easy</code>, <code>normal</code>, <code>hard</code>.</td></tr><tr><td><code>gamemode</code></td><td>Dropdown: <code>survival</code>, <code>creative</code>, <code>hardcore</code>, <code>adventure</code>, <code>spectator</code>.</td></tr><tr><td>Everything else</td><td>Plain text input.</td></tr><tr><td>Comments &amp; unknown lines</td><td>Preserved verbatim on save — only <code>key=value</code> lines are rewritten.</td></tr><tr><td>Nest restriction</td><td>Only servers in the Minecraft nest (ID <code>1</code>) can use the editor; the backend rejects others.</td></tr></tbody></table><h2 id="extension-manifest-conf-yml" tabindex="-1">Extension manifest (<code>conf.yml</code>) <a class="header-anchor" href="#extension-manifest-conf-yml" aria-label="Permalink to &quot;Extension manifest (`conf.yml`)&quot;">​</a></h2><p>Located at <code>blueprint/blueserverproperties/conf.yml</code> in the repo. You normally never edit these — Blueprint reads them at install time.</p><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>info.identifier</code></td><td><code>blueserverproperties</code></td><td>Extension identifier — used in all paths and URLs.</td></tr><tr><td><code>info.version</code></td><td><code>1.12.4</code></td><td>Extension version (shown on the admin page).</td></tr><tr><td><code>info.target</code></td><td><code>beta-2026-06</code></td><td>Blueprint version the extension targets.</td></tr><tr><td><code>info.compatibility</code></td><td><code>beta-2026-01/02/05/06</code></td><td>Blueprint versions accepted at install time.</td></tr><tr><td><code>admin.view</code> / <code>admin.controller</code></td><td><code>view.blade.php</code> / <code>controller.php</code></td><td>The admin settings page.</td></tr><tr><td><code>dashboard.components</code></td><td><code>components</code></td><td>React components (editor + <code>NavButtonUpdater</code>).</td></tr><tr><td><code>data.directory</code></td><td><code>data</code></td><td>Ships <code>data/PanelFiles/</code>, the Blueprint-free variant.</td></tr><tr><td><code>requests.app</code></td><td><code>controllers</code></td><td>Client API controllers.</td></tr><tr><td><code>requests.routers.client</code></td><td><code>routes.php</code></td><td>Client API router, mounted at <code>/api/client/extensions/blueserverproperties</code>.</td></tr></tbody></table>',11)])])}const m=t(n,[["render",a]]);export{u as __pageData,m as default};
